/* FinCom's balance sheet matched with the audited one (owner,        */
/* 29-Oct-2026: "match the figures uploaded by the last year balance  */
/* sheet and generated by FinCom, identify the difference and make it */
/* correct as per balance uploaded")                                  */
/* ================================================================== */
// The audited balance sheet as at the year's end is the one uploaded as "last year's balance sheet" of the next year
// (FinPyBs.latest(fy + 1): one store, one upload for both). FinRecon:
//   compare(fy)   head by head of the balance sheet, and code by code within (PPE by class, net): audited · FinCom ·
//                 difference, in rupees; FinCom's figure from the trial balance's final column with the year's profit in the
//                 surplus (or the capital accounts), each with its ledgers.
//   propose(fy)   for each difference, in this order: (a) a ledger mapped to another head than the audited balance sheet
//                 shows (a ledger named in its note; else one ledger, or two or three from one head, whose balance is the
//                 difference both ways); (b) an audit entry not in Tally: provision for income tax, depreciation, expenses
//                 payable, deferred tax, as an adjustment dated the balance sheet date (FinCom's own list, never posted to
//                 Tally); (c) how much of the profit's difference they explain. What nothing explains stays listed.
//   accept / reject / acceptAll / undo   each recorded in b.fs.recon[fy].log (who, when; undone entries kept, marked);
//                 accepted entries carry {recon, carry}: next year's opening balances include them (FinSt.tb) until
//                 setInTally(fy, true) says they are passed in Tally. journal(fy): the entries, for Tally.
const FinRecon = (() => {
  const N = v => +v || 0, R2 = v => { const r = Math.round(v * 100) / 100; return r === 0 ? 0 : r; };
  const C = () => FinSt.CODES, DMY = y => FinSt.DMY(y);
  const asAtOf = fy => String(N(fy) + 1) + "0331", fyl = fy => N(fy) + "-" + String(N(fy) + 1).slice(2);
  const who = o => (o && o.by) || (typeof Cloud === "object" && Cloud.st && Cloud.st.email) || ((typeof S === "object" && S.firm) ? (S.firm.partner || S.firm.firmName) : "") || "this computer";
  const save = () => { if (typeof saveBooks === "function") saveBooks(); };
  const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
  function st(fy){ const b = S.books; b.fs = b.fs || {}; b.fs.recon = Object.assign({}, b.fs.recon); const r = b.fs.recon[fy] = Object.assign({log: [], rejected: {}, inTally: false}, b.fs.recon[fy]); return r; }
  const audited = fy => (typeof FinPyBs === "object" ? FinPyBs.latest(String(N(fy) + 1)) : null);
  // a code's place in the comparison: a PPE class by its gross code (gross and depreciation together, the net block),
  // the profit earlier in the year in the surplus
  function keyOf(code){
    const c = C()[code]; if (!c) return code;
    if (c.ppe){ const z = FinSt.PPE.concat(FinSt.INT).find(p => p[0] === c.cls); return z ? z[2] : code; }
    return code === "4E" ? "4A" : code;
  }
  const labelOf = k => { const z = FinSt.PPE.concat(FinSt.INT).find(p => p[2] === k); return z ? z[1] + " (net block)" : (C()[k] || {}).label || k; };

  function compare(fy){
    fy = String(fy);
    const v = audited(fy); if (!v) return {none: true, asAt: DMY(asAtOf(fy))};
    const d = FinSt.build(fy, {unit: 1, dec: 2}); if (d.error) return {error: d.error, asAt: DMY(asAtOf(fy))};
    const u = N(v.unit) || 1, tol = Math.max(0.005, u / 2), aud = {}, audLines = {}, fin = {}, led = {};
    (v.lines || []).forEach(z => { const c = C()[z.code]; if (!z.use || !c || c.side !== "BS") return; const k = keyOf(z.code); aud[k] = (aud[k] || 0) + N(z.amt) * u; (audLines[k] = audLines[k] || []).push(z); });
    d.tb.rows.forEach(r => { const c = C()[r.code]; if (!c || c.side !== "BS") return; const k = keyOf(r.code); fin[k] = (fin[k] || 0) + c.sign * r.final;
      (led[k] = led[k] || []).push({ledger: r.ledger, code: r.code, final: r.final, synthetic: !!r.synthetic}); });
    // this year's profit sits in the surplus (a company) or the partners' capital (a firm)
    const pat = R2(-d.tb.rows.filter(r => r.code && C()[r.code] && C()[r.code].side === "PL").reduce((s, r) => s + r.final, 0)), pk = d.kind === "co" ? "4A" : "3P";
    fin[pk] = (fin[pk] || 0) + pat;
    const heads = [];
    Object.entries(d.bs.sections).forEach(([sec, S2]) => S2.lines.forEach(l => {
      const keys = Array.from(new Set(Object.keys(aud).concat(Object.keys(fin)))).filter(k => FinSt.bsLineOf(k) === l.id);
      const codes = keys.map(k => { const a = R2(N(aud[k])), f = R2(N(fin[k])), df = R2(a - f);
        return {key: k, label: labelOf(k), aud: a, fin: f, diff: Math.abs(df) <= tol ? 0 : df, ledgers: (led[k] || []).filter(z => Math.abs(z.final) >= 0.005), lines: (audLines[k] || []).map(z => z.label)}; })
        .filter(z => z.aud || z.fin);
      if (!codes.length) return;
      const a = R2(codes.reduce((s, z) => s + z.aud, 0)), f = R2(codes.reduce((s, z) => s + z.fin, 0)), df = R2(a - f);
      heads.push({id: l.id, sec, label: l.label, aud: a, fin: f, diff: Math.abs(df) <= tol ? 0 : df, codes});
    }));
    return {asAt: DMY(asAtOf(fy)), asAtYmd: asAtOf(fy), fy, v: v.v, file: v.file || "", unit: u, tol, heads, bad: heads.filter(h => h.diff).length, kind: d.kind, pat, d, aud, fin, audLines};
  }

  // ---------- the proposals ----------
  function propose(fy){
    fy = String(fy);
    const cmp = compare(fy); if (cmp.none || cmp.error) return Object.assign({mapping: [], adjustments: [], left: [], rejected: [], profit: null}, cmp);
    const r = st(fy), rej = r.rejected || {}, d = cmp.d, tol = cmp.tol, K = FinSt.codes(d.kind), map = (S.books.fs || {}).map || {};
    const diffH = {}; cmp.heads.forEach(h => { diffH[h.id] = h.diff; });
    const hlabel = {}; cmp.heads.forEach(h => { hlabel[h.id] = h.label; });
    Object.values(d.bs.sections).forEach(S2 => S2.lines.forEach(l => { hlabel[l.id] = hlabel[l.id] || l.label; }));
    const codeDiff = {}; cmp.heads.forEach(h => h.codes.forEach(z => { codeDiff[z.key] = z.diff; }));
    const leds = d.tb.rows.filter(x => !x.synthetic && x.code && C()[x.code] && C()[x.code].side === "BS" && Math.abs(x.final) >= 1).map(x => ({ledger: x.ledger, code: x.code, head: FinSt.bsLineOf(x.code), b: x.final}));
    const mapping = [], moved = new Set(), sg = c => C()[c].sign;
    const add = (L, to, why) => {
      const id = "map:" + L.ledger + ">" + to; if (rej[id] || moved.has(L.ledger)) return false;
      const th = FinSt.bsLineOf(to);
      diffH[L.head] = R2(N(diffH[L.head]) + sg(L.code) * L.b); diffH[th] = R2(N(diffH[th]) - sg(to) * L.b);
      codeDiff[keyOf(L.code)] = R2(N(codeDiff[keyOf(L.code)]) + sg(L.code) * L.b); codeDiff[keyOf(to)] = R2(N(codeDiff[keyOf(to)]) - sg(to) * L.b);
      moved.add(L.ledger);
      mapping.push({id, kind: "map", ledger: L.ledger, from: L.code, to, amount: R2(L.b), fromHead: hlabel[L.head] || L.head, toHead: hlabel[th] || th, why, hand: !!map[L.ledger]});
      return true;
    };
    // (a1) a ledger named in the audited balance sheet's notes, under another head
    const nk = t => String(t || "").toUpperCase().replace(/&/g, "AND").replace(/[^A-Z0-9]+/g, "");
    Object.values(cmp.audLines).flat().forEach(z => {
      if (z.face) return; const L = leds.find(x => nk(x.ledger) === nk(z.label) && nk(z.label).length >= 4);
      if (L && K[z.code] && FinSt.bsLineOf(z.code) && FinSt.bsLineOf(z.code) !== L.head) add(L, z.code, "named in the audited balance sheet: " + (z.sub || z.head ? String(z.sub || z.head).replace(/^note\s*\d+\s*/i, "") + ": " : "") + z.label);
    });
    // (a2) by amount: the ledger (or two or three from one head) whose balance is a head's difference, and the head it
    // leaves the better for it
    const targetCode = id => { const h = cmp.heads.find(x => x.id === id); if (!h) return "";
      const want = Math.sign(diffH[id]), cs = h.codes.filter(z => Math.sign(N(codeDiff[z.key])) === want && Math.abs(N(codeDiff[z.key])) >= 1 && K[z.key]).sort((a, z) => Math.abs(N(codeDiff[z.key])) - Math.abs(N(codeDiff[a.key])));
      return cs.length ? cs[0].key : ""; };
    for (let round = 0; round < 12; round++){
      let hit = false;
      const targets = Object.keys(diffH).filter(id => Math.abs(diffH[id]) >= 1).sort((a, z) => Math.abs(diffH[z]) - Math.abs(diffH[a]));
      for (const Y of targets){
        const tc = targetCode(Y); if (!tc) continue;
        const dY = diffH[Y], sY = sg(tc), free = leds.filter(L => !moved.has(L.ledger) && L.head !== Y && Math.abs(N(diffH[L.head])) >= 1);
        const one = free.filter(L => Math.abs(sY * L.b - dY) <= tol && Math.abs(N(diffH[L.head]) + sg(L.code) * L.b) < Math.abs(N(diffH[L.head])));
        if (one.length === 1){ const z = (cmp.audLines[tc] || [])[0]; hit = add(one[0], tc, "by amount: the audited balance sheet shows it under " + hlabel[Y] + (z ? " (" + z.label + ")" : "")); if (hit) break; continue; }
        if (one.length > 1) continue;   // more than one ledger fits: no guess
        // two or three ledgers from one head, explaining both heads' differences
        let found = null, many = false;
        Array.from(new Set(free.map(L => L.head))).forEach(X => {
          const pool = free.filter(L => L.head === X).sort((a, z) => Math.abs(z.b) - Math.abs(a.b)).slice(0, 25);
          for (let i = 0; i < pool.length; i++) for (let j = i + 1; j < pool.length; j++){
            const two = [pool[i], pool[j]], fits = set => { const sb = set.reduce((s, L) => s + L.b, 0); return Math.abs(sY * sb - dY) <= tol && Math.abs(N(diffH[X]) + set.reduce((s, L) => s + sg(L.code) * L.b, 0)) <= tol; };
            if (fits(two)){ if (found) many = true; else found = two; }
            for (let k = j + 1; k < pool.length; k++){ const three = two.concat([pool[k]]); if (fits(three)){ if (found) many = true; else found = three; } }
          }
        });
        if (found && !many){ const z = (cmp.audLines[tc] || [])[0]; found.forEach(L => add(L, tc, "by amount, with " + (found.length - 1) + " other ledger" + (found.length > 2 ? "s" : "") + ": the audited balance sheet shows them under " + hlabel[Y] + (z ? " (" + z.label + ")" : ""))); hit = true; break; }
      }
      if (!hit) break;
    }
    // (b) audit entries not in Tally, on what the mapping leaves
    const rows = d.tb.rows, fyLabel = fyl(fy), date = asAtOf(fy), adjustments = [];
    const ledOf = (code, pref) => { const xs = rows.filter(x => !x.synthetic && x.code === code); return (pref ? xs.find(x => pref.test(x.ledger)) : null) || xs[0] || null; };
    const adj = (kind, key, dr, cr, amt, why, codes) => {
      const id = "adj:" + kind + ":" + key; if (rej[id] || amt < 1) return;
      const cs = {}; Object.entries(codes || {}).forEach(([l, c]) => { const cur = (rows.find(x => x.ledger === l) || {}).code; if (cur !== c) cs[l] = c; });
      adjustments.push({id, kind, key, dr, cr, amt: R2(amt), date, narr: "To match audited balance sheet: " + why, codes: cs, drCode: (codes || {})[dr] || (rows.find(x => x.ledger === dr) || {}).code, crCode: (codes || {})[cr] || (rows.find(x => x.ledger === cr) || {}).code});
    };
    const hl = code => hlabel[FinSt.bsLineOf(code)] || "";
    // provision for income tax
    const t = N(codeDiff["7D"]);
    if (Math.abs(t) >= 1){
      const taxL = ledOf("22A", /CURRENT/i), dr = taxL ? taxL.ledger : "Income Tax - Current Year (as audited)";
      const pv = rows.find(x => !x.synthetic && x.code === "7D" && x.ledger.includes(fyLabel)), cr = pv ? pv.ledger : "Provision for Income Tax FY " + fyLabel;
      t > 0 ? adj("tax", "7D", dr, cr, t, hl("7D") + " (provision for income tax)", {[dr]: "22A", [cr]: "7D"}) : adj("tax", "7D", cr, dr, -t, hl("7D") + " (provision for income tax, less)", {[dr]: "22A", [cr]: "7D"});
    }
    // depreciation, class by class when the audited note gives the classes, else on the head
    const ppeKeys = FinSt.PPE.concat(FinSt.INT).map(p => p[2]), audPpe = ppeKeys.flatMap(k => cmp.audLines[k] || []), byClass = audPpe.length && audPpe.some(z => !z.face);
    const depAdj = (k, amt) => {
      const z = FinSt.PPE.concat(FinSt.INT).find(p => p[2] === k), intang = FinSt.INT.some(p => p[2] === k), dc = intang ? "34D" : "8E";
      const dl = ledOf(dc), dr = dl ? dl.ledger : (intang ? "Amortisation (as audited)" : "Depreciation (as audited)");
      const al = z && z[3] ? ledOf(z[3]) : null, gl = rows.filter(x => !x.synthetic && x.code === k).sort((a, b2) => b2.final - a.final)[0], cr = al ? al.ledger : gl ? gl.ledger : "Accumulated depreciation - " + (z ? z[1] : "assets") + " (as audited)";
      adj("dep", k, dr, cr, amt, hl(k) + " (depreciation on " + (z ? z[1].toLowerCase() : "the assets") + ")", {[dr]: dc, [cr]: al ? z[3] : k});
    };
    if (byClass) ppeKeys.forEach(k => { if (N(codeDiff[k]) <= -1) depAdj(k, -N(codeDiff[k])); });
    else if (N(diffH.ppe) <= -1){ const big = ppeKeys.filter(k => FinSt.PPE.some(p => p[2] === k)).sort((a, z) => N(cmp.fin[z]) - N(cmp.fin[a]))[0]; if (big) depAdj(big, -N(diffH.ppe)); }
    // expenses payable
    const e = N(codeDiff["5F"]);
    if (e >= 1){ const pl = ledOf("5F"); const cr = pl ? pl.ledger : "Provision for Expenses (as audited)", dr = "Expenses provided at the year end (as audited)"; adj("exp", "5F", dr, cr, e, hl("5F") + " (expenses payable)", {[dr]: "17J", [cr]: "5F"}); }
    // deferred tax
    const dta = N(codeDiff["9A"]), dtl = N(codeDiff["31A"]), dtx = ledOf("22C"), dx = dtx ? dtx.ledger : "Deferred Tax (as audited)";
    if (Math.abs(dta) >= 1){ const a = ledOf("9A"), al = a ? a.ledger : "Deferred Tax Asset (as audited)";
      dta > 0 ? adj("dta", "9A", al, dx, dta, hl("9A") + " (deferred tax)", {[al]: "9A", [dx]: "22C"}) : adj("dta", "9A", dx, al, -dta, hl("9A") + " (deferred tax)", {[al]: "9A", [dx]: "22C"}); }
    if (Math.abs(dtl) >= 1){ const a = ledOf("31A"), al = a ? a.ledger : "Deferred Tax Liability (as audited)";
      dtl > 0 ? adj("dtl", "31A", dx, al, dtl, hl("31A") + " (deferred tax)", {[al]: "31A", [dx]: "22C"}) : adj("dtl", "31A", al, dx, -dtl, hl("31A") + " (deferred tax)", {[al]: "31A", [dx]: "22C"}); }
    // (c) the profit, and what is left once all of it is accepted
    const ph = d.kind === "co" ? "rs" : "sc", isPL = c => !!(C()[c] && C()[c].side === "PL");
    let effect = 0; const after = Object.assign({}, diffH);
    adjustments.forEach(a => { [[a.drCode, a.amt], [a.crCode, -a.amt]].forEach(([c, delta]) => {
      if (!C()[c]) return;
      if (isPL(c)){ effect -= delta; after[ph] = R2(N(after[ph]) + delta); }
      else { const h = FinSt.bsLineOf(c); after[h] = R2(N(after[h]) - C()[c].sign * delta); } }); });
    const left = Object.keys(after).filter(id => Math.abs(after[id]) > tol).map(id => ({id, label: hlabel[id] || id, diff: after[id]}));
    const pdiff = N(diffH[ph]);
    return {asAt: cmp.asAt, fy, heads: cmp.heads, bad: cmp.bad, mapping, adjustments, left, rejected: Object.values(rej).map(z => z.p),
      profit: {head: hlabel[ph], diff: R2(pdiff), explained: R2(effect), left: R2(pdiff - effect)}};
  }

  // ---------- approving ----------
  const find = (fy, id) => { const p = propose(fy); return p.mapping.concat(p.adjustments).find(z => z.id === id) || null; };
  const desc = p => p.kind === "map" ? p.ledger + ": " + p.from + " -> " + p.to + " (" + C()[p.to].label + ")" : "Dr " + p.dr + " / Cr " + p.cr + " " + p.amt.toFixed(2) + " on " + DMY(p.date);
  function accept(fy, id, o){
    fy = String(fy); const p = find(fy, id); if (!p) return null;
    const r = st(fy), by = who(o), at = new Date().toISOString(), m = (S.books.fs || {}).map || {}, e = {id: uid(), kind: "accept", pid: p.id, type: p.kind, what: desc(p), by, at};
    if (p.kind === "map"){ e.ledger = p.ledger; e.prev = m[p.ledger] || ""; FinSt.mapSet(p.ledger, p.to); }
    else {
      e.adjId = uid(); e.codesPrev = {};
      Object.entries(p.codes || {}).forEach(([l, c]) => { e.codesPrev[l] = m[l] || ""; FinSt.mapSet(l, c); });
      FinSt.adjAdd(fy, {dr: p.dr, cr: p.cr, amt: p.amt, narr: p.narr, id: e.adjId, date: p.date, kind: p.kind, recon: true, carry: true, by, at});
    }
    r.log = (r.log || []).concat([e]); save(); return e;
  }
  function acceptAll(fy, kind, o){ const p = propose(fy); return (kind === "map" ? p.mapping : p.adjustments).map(z => accept(fy, z.id, o)).filter(Boolean); }
  function reject(fy, id, o){
    fy = String(fy); const p = find(fy, id); if (!p) return null;
    const r = st(fy), by = who(o), at = new Date().toISOString(), e = {id: uid(), kind: "reject", pid: p.id, type: p.kind, what: desc(p), by, at};
    r.rejected = Object.assign({}, r.rejected, {[p.id]: {p, by, at}}); r.log = (r.log || []).concat([e]); save(); return e;
  }
  function undo(fy, logId, o){
    fy = String(fy); const r = st(fy), e = (r.log || []).find(z => z.id === logId); if (!e || e.undone) return null;
    if (e.kind === "reject"){ const x = Object.assign({}, r.rejected); delete x[e.pid]; r.rejected = x; }
    else if (e.type === "map") FinSt.mapSet(e.ledger, e.prev || "");
    else { FinSt.adjDelId(fy, e.adjId); Object.entries(e.codesPrev || {}).forEach(([l, c]) => FinSt.mapSet(l, c || "")); }
    r.log = r.log.map(z => z.id === logId ? Object.assign({}, z, {undone: {by: who(o), at: new Date().toISOString()}}) : z); save(); return e;
  }
  const log = fy => st(String(fy)).log || [];
  function setInTally(fy, on, o){ const r = st(String(fy)); r.inTally = !!on; r.log = (r.log || []).concat([{id: uid(), kind: "tally", on: !!on, what: on ? "the entries passed in Tally: FinCom stops adding them" : "the entries not in Tally: FinCom adds them again", by: who(o), at: new Date().toISOString()}]); save(); }
  // the accepted entries, as journal vouchers for Tally (FinCom never posts them)
  const journal = fy => ((((S.books.fs || {}).adj || {})[String(fy)]) || []).filter(a => a.recon).map(a => ({date: DMY(a.date || asAtOf(fy)), ymd: a.date || asAtOf(fy), type: "Journal", dr: a.dr, cr: a.cr, amt: R2(N(a.amt)), narr: a.narr || ""}));
  return {compare, propose, accept, acceptAll, reject, undo, log, setInTally, journal, inTally: fy => !!st(String(fy)).inTally, keyOf};
})();

if (typeof globalThis === "object") Object.assign(globalThis, {FinRecon});
/* @react-lazy: end */
